+function segmentToRegex(seg: string): string {
+  let out = "^";
+  for (let i = 0; i < seg.length; i++) {
+    const ch = seg[i];
+    if (ch === "*") {
+      out += "[^/]*";
+    } else if (ch === "?") {
+      out += "[^/]";
+    } else {
+      out += "\\^$.+?()[]{}|".includes(ch) ? "\\" + ch : ch;
+    }
+  }
+  out += "$";
+  return out;
+}
+
+function matchSegment(patSeg: string, pathSeg: string): boolean {
+  return new RegExp(segmentToRegex(patSeg)).test(pathSeg);
+}
+
+function matchSegments(
+  patSegs: string[],
+  pathSegs: string[],
+  pi: number,
+  si: number,
+): boolean {
+  if (pi >= patSegs.length) return si >= pathSegs.length;
+
+  const seg = patSegs[pi];
+
+  if (seg === "**") {
+    if (pi === patSegs.length - 1) {
+      return si < pathSegs.length;
+    }
+    for (let i = si; i <= pathSegs.length; i++) {
+      if (matchSegments(patSegs, pathSegs, pi + 1, i)) return true;
+    }
+    return false;
+  }
+
+  if (si >= pathSegs.length) return false;
+  if (!matchSegment(seg, pathSegs[si])) return false;
+  return matchSegments(patSegs, pathSegs, pi + 1, si + 1);
+}
+
+function matchPattern(pattern: string, path: string): boolean {
+  return matchSegments(pattern.split("/"), path.split("/"), 0, 0);
+}
